'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const m = input[1];
const neighbors = new Int32Array(n);

let pos = 2;
for (let i = 0; i < m; i++) {
  const x = input[pos++] - 1;
  const y = input[pos++] - 1;
  neighbors[x] |= 1 << y;
  neighbors[y] |= 1 << x;
}

const total = 1 << n;
const independent = new Uint8Array(total);
independent[0] = 1;

let answer = 0;
for (let mask = 1; mask < total; mask++) {
  const bit = mask & -mask;
  const index = 31 - Math.clz32(bit);
  const rest = mask ^ bit;

  if (independent[rest] && (neighbors[index] & rest) === 0) {
    independent[mask] = 1;
    answer++;
  }
}

console.log(answer);
